struct RingBuffer {
    RingBuffer(int capacity) : cap(capacity), head(0), count(0) {}

    bool push(int value) {
        if (full()) return false;
        buf[(head + count) % cap] = value;
        ++count;
        return true;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = buf[head];
        head = (head + 1) % cap;
        --count;
        return true;
    }

    int size() const { return count; }
    bool empty() const { return count == 0; }
    bool full() const { return count == cap; }

private:
    static const int MAX_SIZE = 1024;
    int buf[MAX_SIZE];
    int cap;
    int head;
    int count;
};
